from flask import render_template_string

from app import app


PAGE = """<!doctype html><html><head><meta charset=utf-8><meta name=viewport content='width=device-width,initial-scale=1'><title>ContractGuardian | Contract Analyser</title><style>
*{box-sizing:border-box}body{margin:0;min-height:100vh;color:#eaf0fa;background:radial-gradient(circle at 15% 10%,#214774 0,transparent 32%),radial-gradient(circle at 85% 90%,#1d594d 0,transparent 28%),#081326;font:16px Georgia,serif}main{width:min(1080px,calc(100% - 32px));margin:auto;padding:54px 0 74px}.eyebrow{font:700 12px system-ui,sans-serif;letter-spacing:.18em;color:#95c7ff}.hero{display:grid;grid-template-columns:1fr 290px;gap:38px;align-items:end}.hero h1{font-size:clamp(38px,6vw,64px);font-weight:500;line-height:.98;margin:14px 0}.hero p{max-width:650px;color:#c4d2e7;line-height:1.65}.scope{border-left:1px solid #7797ba;padding-left:18px;color:#c5d6e9;line-height:1.55}.scope b{display:block;color:white;margin-bottom:8px}.workspace{display:grid;grid-template-columns:355px 1fr;gap:24px;margin-top:44px}.paper{background:linear-gradient(135deg,#fbf8ed,#ede5d2);color:#182235;border-radius:4px;padding:28px;box-shadow:18px 18px 0 #02091655;position:relative;overflow:hidden}.paper:before{content:'CONTRACT REVIEW';position:absolute;right:-20px;top:20px;transform:rotate(90deg);font:700 10px system-ui,sans-serif;letter-spacing:.2em;color:#50637d55}.paper h2,.findings h2{font-size:22px;font-weight:500;margin:0 0 8px}.paper p{color:#53627a;line-height:1.5}.dropzone{display:block;border:1px dashed #7c8ca2;padding:20px 14px;margin:24px 0 15px;cursor:pointer}.dropzone span{display:block;font:700 13px system-ui,sans-serif;letter-spacing:.05em}.dropzone small{display:block;color:#5c6d85;margin-top:7px;font:13px system-ui,sans-serif}.dropzone input{width:100%;margin-top:14px;font:13px system-ui,sans-serif}.button{width:100%;border:0;border-radius:2px;background:#102b4f;color:#fff;padding:13px;font:700 14px system-ui,sans-serif;letter-spacing:.04em;cursor:pointer}.button:disabled{opacity:.55}.progress{height:5px;background:#d9cfba;margin:22px 0 9px}.progress span{height:100%;display:block;width:0;background:#bd7e31;transition:width .35s}.status{color:#53627a;font:13px system-ui,sans-serif}.findings{border:1px solid #36506f;background:#0c1a30b8;padding:28px;min-height:385px}.findings header{display:flex;justify-content:space-between;gap:12px;align-items:baseline;border-bottom:1px solid #2a405e;padding-bottom:16px}.findings header p{color:#a9bed7;margin:0}.empty{color:#a6b7cb;line-height:1.65;padding:30px 0}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:18px 0}.metric{border:1px solid #29425f;padding:13px;color:#b8cbe0;font:13px system-ui,sans-serif}.metric b{font:500 31px Georgia,serif;color:white;display:block}.issue{border-left:3px solid #d2a557;padding:15px 16px;margin-top:13px;background:#101f36}.issue.high{border-color:#e56b62}.issue-title{font:600 16px system-ui,sans-serif}.meta{font:13px system-ui,sans-serif;color:#9bb0c9;margin-top:5px}.issue p{color:#d4dfed;line-height:1.55}.law{font:13px system-ui,sans-serif;color:#aebfd5;line-height:1.5}.findings a{color:#a7d6ff;font:600 13px system-ui,sans-serif}@media(max-width:760px){main{padding-top:32px}.hero,.workspace{grid-template-columns:1fr}.scope{display:none}.summary{grid-template-columns:1fr}.findings{min-height:0}}</style></head><body><main><section class=hero><div><div class=eyebrow>CONTRACTGUARDIAN / INDIA</div><h1>Contract<br>analyser.</h1><p>Review the clauses that could create commercial or legal exposure before you sign. Each finding includes an explainable risk score, a suggested improvement, and a relevant Indian-law reference where available.</p></div><aside class=scope><b>Review standard</b>Decision support only. This analysis does not replace advice from qualified Indian counsel.</aside></section><section class=workspace><aside class=paper><h2>New review</h2><p>Upload a text-based contract PDF to begin a clause-by-clause analysis.</p><label class=dropzone><span>SELECT CONTRACT PDF</span><small>PDF · text-based files work best</small><input id=file type=file accept='.pdf,application/pdf'></label><button class=button id=start>Analyse contract</button><div id=work hidden><div class=progress><span id=bar></span></div><div class=status id=status>Preparing your review…</div></div></aside><section class=findings><header><div><h2>Findings</h2><p id=subtitle>Ready when you are.</p></div><span class=eyebrow>RISK DOSSIER</span></header><div id=results class=empty>Upload a contract to see flagged clauses, their confidence scores, suggested revisions, and linked legal references.</div></section></section></main><script>
const file=document.querySelector('#file'),button=document.querySelector('#start'),work=document.querySelector('#work'),bar=document.querySelector('#bar'),status=document.querySelector('#status'),results=document.querySelector('#results'),subtitle=document.querySelector('#subtitle');function update(progress,message){bar.style.width=progress+'%';status.textContent=message}function render(data){const flagged=data.clauses.filter(c=>c.status==='success'&&c.review&&c.review.severity!=='Low'),high=flagged.filter(c=>c.review.severity==='High').length;subtitle.textContent=`${data.document.clauses_analyzed} clauses analysed · ${flagged.length} require review`;results.className='';results.innerHTML=`<div class=summary><div class=metric><b>${data.document.clauses_analyzed}</b>clauses analysed</div><div class=metric><b>${flagged.length}</b>require review</div><div class=metric><b>${high}</b>high risk</div></div><p><a href='${data.report_download_url}'>Download the review PDF</a></p>`+(flagged.length?flagged.map(c=>`<article class='issue ${c.review.severity==='High'?'high':''}'><div class=issue-title>${c.clause_id} · ${c.review.severity} risk · ${c.review.risk_score}/100</div><div class=meta>Model confidence ${Math.round(c.review.confidence*100)}%</div><p>${c.review.suggestion}</p>${c.review.laws.map(l=>`<div class=law><b>${l.section}</b><br>${l.summary}<br><a target=_blank href='${l.url}'>Read India Code reference</a></div>`).join('')}</article>`).join(''):'<p class=empty>No medium- or high-risk clauses were automatically flagged. A qualified review is still recommended.</p>')}async function poll(id){const response=await fetch('/api/reviews/'+id),data=await response.json();if(data.status==='failed'){update(100,data.error);button.disabled=false;return}if(data.status==='completed'){update(100,'Review complete.');render(data.result);button.disabled=false;return}update(data.progress,data.message);setTimeout(()=>poll(id),900)}button.onclick=async()=>{if(!file.files[0]){update(0,'Choose a PDF first.');work.hidden=false;return}button.disabled=true;work.hidden=false;results.className='empty';results.textContent='Your contract is being prepared for analysis…';update(4,'Uploading contract…');const form=new FormData();form.append('file',file.files[0]);try{const response=await fetch('/api/reviews',{method:'POST',body:form}),data=await response.json();if(!response.ok)throw Error(data.error||'Upload failed');poll(data.review_id)}catch(error){update(100,error.message);button.disabled=false}};</script></body></html>"""


def home():
    return render_template_string(PAGE)


app.view_functions["home"] = home


if __name__ == "__main__":
    app.run(host="127.0.0.1", port=5000, debug=False, use_reloader=False, threaded=True)
